SELECT (DATE_TRUNC('HOUR', "METERING_HOUR")) AS "TIME_BUCKET", SUM(CREDITS_COMPUTE) AS "COST_BY_WAREHOUSE_CREDITS" FROM (SELECT m."WAREHOUSE_NAME" AS WAREHOUSE_NAME, m."WAREHOUSE_ID" AS WAREHOUSE_ID, (DATE_TRUNC('HOUR', (TRY_CAST(m."START_TIME" AS TIMESTAMP)))) AS METERING_HOUR, (CAST(m."CREDITS_USED_COMPUTE" AS DECIMAL(38, 9))) AS CREDITS_COMPUTE, (CAST(m."CREDITS_USED_CLOUD_SERVICES" AS DECIMAL(38, 9))) AS CREDITS_CLOUD_SERVICES, (CAST(COALESCE(a.CREDITS_ATTRIBUTED, 0) AS DECIMAL(38, 9))) AS CREDITS_ATTRIBUTED, (CAST(m."CREDITS_USED_COMPUTE" - COALESCE(a.CREDITS_ATTRIBUTED, 0) AS DECIMAL(38, 9))) AS CREDITS_IDLE, r.WAREHOUSE_RANK AS WAREHOUSE_RANK /* Whole-window rank by total compute, so concentration metrics can ask for */ /* "the top N warehouses" without a correlated subquery per row. */ FROM warehouse_metering_history AS m LEFT JOIN (SELECT "WAREHOUSE_NAME" AS WAREHOUSE_NAME, (DATE_TRUNC('HOUR', (TRY_CAST("START_TIME" AS TIMESTAMP)))) AS ATTRIBUTION_HOUR, SUM((CAST("CREDITS_ATTRIBUTED_COMPUTE" AS DECIMAL(38, 9)))) AS CREDITS_ATTRIBUTED FROM query_attribution_history GROUP BY 1, 2) AS a ON a.WAREHOUSE_NAME = m."WAREHOUSE_NAME" AND a.ATTRIBUTION_HOUR = (DATE_TRUNC('HOUR', (TRY_CAST(m."START_TIME" AS TIMESTAMP)))) LEFT JOIN (SELECT "WAREHOUSE_NAME" AS WAREHOUSE_NAME, DENSE_RANK() OVER (ORDER BY SUM("CREDITS_USED_COMPUTE") DESC) AS WAREHOUSE_RANK FROM warehouse_metering_history GROUP BY 1) AS r ON r.WAREHOUSE_NAME = m."WAREHOUSE_NAME") AS base GROUP BY (DATE_TRUNC('HOUR', "METERING_HOUR")) ORDER BY "COST_BY_WAREHOUSE_CREDITS" DESC, "TIME_BUCKET" LIMIT 100
